INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(371100, 0, 3711, 0, 0, 13, 'Sholazar Basin', 'Sholazar Basin is a hidden jungle in the northwest of Northrend, ringed by mountains, where the frozen continent gives way to steaming rivers, mangrove swamps and warm rain. Great crystal pillars rise around its edges, works of the titans, and the gorlocs who call themselves the Oracles tend ancient stone shrines they believe the Great Ones left for them. The wolvar of the Frenzyheart Tribe, newcomers to the basin, mean to take the land for their own, and the two peoples are at war. Rhinos, dreadsabers, primordial drakes and hydras roam the wilds, and they have drawn the famous hunter Hemet Nesingwary, whose expedition camps on a river in the west. The Venture Company digs at the foot of a pillar for its crystals. And in the east the Scourge has broken in: blight creeps over the Lost Lands, one of the pillars lies shattered, and a towering guardian, the Avatar of Freya, holds the line against the dead.', 'quest 12521 description (a lush paradise in the midst of this frozen continent); quest 12612 description (titans shaped life here; five crystal pillars surround the basin; one destroyed); quest 12576 description (the Great Stones are here from when the Great Ones made us); creature_text 28215 (Dajik: Frenzyheart came here not long ago for a new home); npc_text 13359 (Rakjak: Frenzyheart will take land for own); quests 12520, 12549, 12551, 12603, 12683 (rhinos, dreadsabers, crocolisks, primordial drakes, hydras); quests 12523, 12688 (Venture Company at the Suntouched Pillar); quest 12803 description (the Lost Lands; the lifewarden fighting the Scourge); zone_areas: Avatar of Freya 27801 in 4386; Bonescythe Ravager and Blighted Corpse spawns in 4283, 4297, 4295; warcraft.wiki.gg/wiki/Sholazar_Basin (tropical basin in northwestern Northrend; pillars; Wrath-era events only)'),
(371101, 1, 3711, 1, 0, 13, 'Wildgrowth Mangal', 'The Wildgrowth Mangal is a tangled mangrove swamp east of the Nesingwary Base Camp, its tall trees heavy with oranges, bananas and papayas that hang well out of reach. Emperor cobras and mangal crocolisks hunt among the roots, and the gorloc oracles prize the cobras'' fangs. Not every visitor arrived by choice. The Venture Company has been shooting flying machines out of the sky over the swamp, and the wreck of one lies where it fell, its engine still whole. Nearby hangs Monte Muzzleshot, who parachuted into the mangal on his way to Hemet''s camp with supplies, dangling from a tree by his tangled chute and waiting for someone to cut him down.', 'quest 12634 description (Wildgrowth Mangal to the east; trees laden with fruit too high to reach); quests 12543 and 12571 (emperor cobras; cobra fangs for the oracle''s necklace); quest 12551 description (mangal crocolisks in the Wildgrowth Mangal); quest 12522 description (Venture Company shot down another flying machine where Monte parachuted into the swamp; retrieve the engine); quest 12521 description and reward text (Monte bringing supplies; have him send someone to cut me down); creature_addon 27987 aura 50544 Cosmetic - Parachute Stuck; zone_areas 4293: Monte Muzzleshot 27987, Flying Machine Engine 190447, Emperor Cobra x60, Mangal Crocolisk x24'),
(371102, 1, 3711, 2, 0, 13, 'Nesingwary Base Camp', 'On a river in the west of the basin, Hemet Nesingwary''s expedition has made its base camp after a hard landing: the ship that brought it ran aground, the brewer Grimbooze Thunderbrew lost his best kegs, and Weslex Quickwrench''s flying machine, the Spirit of Gnomeregan, came through too damaged to fly, leaving the camp no way to send its reports home. Debaar, whom everyone seems to blame for the wreck, is tired of hearing about it. The hunters have not let it slow them. Hemet, Buck Cantwell, Debaar and Drostan test newcomers against the basin''s beasts, Professor Calvert watches the strange weather, and Purser Boulian admits this is not what she signed up for, though at least it is warm.', 'quest 12522 description (the ship ran aground; flying machine damaged; no means to send reports); quest 12634 description (Grimbooze''s kegs burst when the ship ran aground); npc_text 13322 (Weslex: she didn''t survive the crash); npc_text 13506 (Debaar: everyone looks at me as if I crashed the ship); quest 12551 description (no comments about crashing the ship); quests 12520, 12549, 12551, 12589 (Hemet, Buck, Debaar, Drostan test newcomers); quest 12804 (Korg the Cleaver, ship''s cook); quest 12696 and 12803 descriptions (the professor and the weather pattern); npc_text 13431 (Purser Boulian: not what I signed up for, at least it''s warm); zone_areas 4284: Hemet 27986, Buck 28031, Debaar 28032, Weslex 28033, Drostan 28328, Korg 28046, Grimbooze 29157, Calvert 28266, Boulian 28038'),
(371103, 1, 3711, 3, 0, 13, 'The Bones of Nozronn', 'Across the river south of the Nesingwary Base Camp lie the Bones of Nozronn, the vast remains of a beast the gorlocs revere. Close by, in a small lean-to, lives Oracle Soo-rahm, who tends the bones and speaks for them. He asks no question of those who come to him, for he holds that mighty Nozronn already knows what is in their hearts. Still, the bones do not speak for nothing: a stranger must first bring offerings, such as the best fangs of the emperor cobras for the oracle''s necklace, before Soo-rahm will light the incense.', 'quest 12526 description (native sage keeps a lean-to near the Bones of Nozronn, across the river to the south); quests 12543 and 12544 descriptions (offerings of cobra fangs for the oracle''s necklace; incense; Nozronn will answer your heart''s question); quest 12526 reward text (Rahm''s shrine); zone_npcs: Oracle Soo-rahm 28191 at 25.6,66.5 near area 4286'),
(371104, 1, 3711, 4, 0, 13, 'Swindlegrin''s Dig', 'Swindlegrin''s Dig is a Venture Company mine on the far side of the Suntouched Pillar, northeast of the Nesingwary Base Camp. Goblin excavators and hired ruffians work it under Foreman Swindlegrin, who watches over the whole operation from a high platform with his ogre bodyguard, Meatpie, never far away. The goblins have decided the pillar and its crystals are theirs, and they do not welcome rivals: they shoot down the expedition''s supply flights and their workers harass Hemet''s scouts. They also hold a prisoner, an engineer of the expedition who came to study the crystals, and they hold her at the dig.', 'quests 12523, 12524, 12525 descriptions (far side of the Suntouched Pillar to the northeast; antagonizing scouts and shooting down supply flights; Swindlegrin and his ogre bodyguard Meatpie on a platform); quest 12688 description (goblins decided they own this pillar and its crystals; Helice overpowered while taking samples); creature_text 28787 (never keep the prisoner near the explosives); zone_areas 4391: Venture Co. Excavator x39, Ruffian x17, Foreman Swindlegrin 28186, Meatpie 28188, Engineer Helice 28787, Explosion Guy 28789'),
(371105, 1, 3711, 5, 0, 13, 'Lakeside Landing', 'River''s Heart is the great lake near the center of the basin where its rivers converge, and on its northeastern shore lies Lakeside Landing. When the trouble with the Venture Company began, Hemet sent Marvin Wobblesprocket and his wife Tamara here with their flying machines, to set up a camp that could relay supplies into the basin and survey the land around it. Marvin gets so absorbed in his work that he hardly notices visitors. Tamara hopes to sharpen her own hunting skills between repairs, and Pilot Vic is ready to fly, if only he can find a copilot.', 'quest 12651 description (Hemet sent Marvin and his wife Tamara with flying machines to River''s Heart to set up a relay and survey; the lake where the rivers converge; northeast shore); quest 12651 reward text (forgive Marvin, absorbed in his work); quest 12654 description (Tamara hoped to work on her hunting between repairs); quest 12696 description (a pilot ready to work but needs a copilot); zone_areas 4383: Pilot Vic 28746, Tamara 28568, Marvin 28574, Flying Machine 24653'),
(371106, 1, 3711, 6, 0, 13, 'Frenzyheart Hill', 'Frenzyheart Hill is the home of the Frenzyheart Tribe, wolvar who came to Sholazar not long ago looking for a new home. High-Shaman Rakjak rules here, and he means for his people to take the basin for their own: the gorlocs, whom the wolvar call big-tongues, must leave or be killed. Elder Harkek is the gentler voice of the hill. The Frenzyheart can be vicious, he admits, but they are good people, friends with the smart and the strong; they just do not like the dumb. Trackers and berserkers guard the slopes, pups tumble between the huts, and young Rejek dreams aloud of the mighty warrior he will one day be.', 'creature_text 28215 group 0 (Dajik: Frenzyheart came here not long ago for new home); npc_text 13359 (Rakjak: Frenzyheart will take land for own; big-tongues will leave or we kill them); npc_text 13360 (Harkek: vicious but good people; friends with smart and strong; don''t like dumb); npc_text 13438 (Rejek: one day, Rejek be mighty warrior); zone_areas 4292: Rakjak 28082, Harkek 28138, Rejek 29043, Frenzyheart Tracker x10, Berserker x5, Pup x4; quest 12760 description (berries we keep from other lands we came from)'),
(371107, 1, 3711, 7, 0, 13, 'Rainspeaker Canopy', 'Rainspeaker Canopy is a gorloc village in the boughs of an enormous tree, the home of the Rainspeaker tribe and the heart of the Oracles. Its people keep the Great Rain Stone, which they believe was left by the Great Ones who made them, and they care for it with offerings of shinies dug from the earth; in return, they say, it takes care of them. High-Oracle Soo-say leads them, and Oracle Soo-nee keeps songs of wind, water and crystal for friends with time to learn them. They call outsiders dryskins, and they call the wolvar puppy-men.', 'npc_text 13361 (Soo-say: this the Great Rain Stone; we bring it shinies and it take care of us); creature_text 28120 group 2 (Lafoo: big comfy tree, good home); quest 12576 description (the Great Stones are here from when the Great Ones made us); npc_text 13457 (Soo-nee: teach you good song); quests 12726, 12735, 12736, 12737 (songs of wind and water, cleansing, reflection at the pillars, fecundity); quests 12570-12574 (dryskin; puppy-men); zone_areas 4291: Soo-say 28027, Soo-nee 29006, Soo-dow 29149, Rainspeaker Warrior x6, Oracle x4, Gorloc Hatchling x3'),
(371108, 1, 3711, 8, 0, 13, 'Mistwhisper Refuge', 'Mistwhisper Refuge lies near Bittertide Lake in the northwest of the basin, the home of the Mistwhisper gorlocs and their Great Mist Stone. The stone is one of the Oracles'' weather shrines, fed with crystals, and the Mistwhispers use it to call up mists that hide the land all around. They know just which crystals to use; set the wrong ones before the stone and its clouds, rain and lightning run wild. Their neighbors are no comfort. North of the village, at the Spearborn Encampment, Frenzyheart spearbearers and scavengers have pitched a camp of their own.', 'quest 12537 description (crystals power the rain shrines; the wrong crystals make the clouds and rain go crazy); creature_text 28216 group 3 (Zepik: mist big-tongues cover whole area with mist); creature_text 28121 group 2 (Jaloot: Mistcaller really good at controlling weather; know which crystals to use); quest 12734 description (Mistwhispers far to the northwest near Bittertide Lake); quests 12575, 12576 descriptions (wolvar camp to the north); zone_areas 4306: Mistwhisper Warrior x19, Oracle x19, Arranged Crystal Formation 190502; 4308: Frenzyheart Spearbearer x12, Scavenger x11, Mistwhisper Treasure 190578'),
(371109, 1, 3711, 9, 0, 13, 'Kartak''s Hold and Sparktouched Haven', 'In the far southwest of the basin the war between the wolvar and the gorlocs burns hottest. Kartak''s Hold is a Frenzyheart stronghold, crowded with ravagers and hunters, and close beside it lies Sparktouched Haven, where the Sparktouched gorlocs guard their Great Lightning Stone. The two camps are hardly apart at all. Sparktouched warriors and oracles fight the wolvar among the huts of both, and neither side gives ground for long.', 'zone_areas 4287: Frenzyheart Ravager x68, Hunter x54, Sparktouched Warrior x2, Oracle x1; 4288: Sparktouched Warrior x54, Oracle x54, Frenzyheart Ravager x27, Hunter x19; npc_text 13452 (Soo-dow: great battle still going on at Sparktouched Haven); quest 12703 description (big battle at Kartak''s Hold to the southwest); quests 12761, 12762 descriptions (Sparktouched Haven in the far southwest)'),
(371110, 1, 3711, 10, 0, 13, 'Dorian''s Outpost', 'Dorian''s Outpost is the expedition''s northern camp, pitched across Bittertide Lake by Dorian Drakestalker, who came looking for bigger game than rhinos and cats. He found it. Primordial drakes rule the Savage Thicket to the north and east, beasts that can devour a man whole, and their queen, Broodmother Slivina, nests on a perch at its northern edge. Farther on lie the Bonefields, where goretalon rocs feed on the corpses of old mammoths. In camp, Zootfizzle raises the hatchlings Dorian brings in and declares the outpost a cog-free zone, and Colvin Norrington gathers talons and other reagents for Archmage Pentarus of Dalaran, who helped fund the expedition.', 'quest 12595 description (Dorian went north across Bittertide Lake and set up camp; primordial drakes); quest 12603 description (drakes occupy most of the area to the north and east; devour a man whole); quest 12614 description (Slivina''s perch at the northern edge of the Savage Thicket); quests 12658, 12681 descriptions (Bonefields beyond the drakes; rocs feed on the corpses of old mammoths); npc_text 13306 (Zootfizzle: cog-free zone); quest 12605 reward text (hatchlings for Zootfizzle); quest 12681 description and npc_text 13352 (Colvin gathering for Archmage Pentarus); quest 12521 description (Pentarus helped fund the expedition); zone_areas 4369: Dorian 28376, Zootfizzle 28374, Colvin 28771; 4376: Primordial Drake x10; 4368: Goretalon Roc x25, Goretalon Matriarch; Broodmother Slivina 28467 (one spawn)'),
(371111, 1, 3711, 11, 0, 13, 'The Crystal Pillars', 'Great pillars of crystal rise around the edges of Sholazar Basin, and four of them still stand: the Glimmering, the Suntouched, the Mosslight and the Skyreach. They are works of the titans, and the gorlocs, who call their makers the Great Ones, hold them sacred and teach songs to be played at their summits. Blue crystal formations from the Skyreach gather along the southern river, and the Venture Company digs in the shadow of the Suntouched. At the Glimmering Pillar, the servants of Freya stand watch, and they are not alone there: cultists have been seen skulking at its foot.', 'quest 12736 description (Glimmering, Suntouched, Mosslight and Skyreach Pillars; Lifeblood Pillar broken, other pillars still good); quest 12612 description (five crystal pillars); quest 12535 description (blue crystals along the river to the south); zone_areas 4388: Skyreach Crystal Formation x20; quests 12523, 12525 (Swindlegrin''s Dig beyond the Suntouched Pillar); zone_areas 4307: Servant of Freya 28320 x14, Cultist Saboteur 28538 x8, Freya''s Presence 28563; creature_text 28121 group 3 (Jaloot: Great Ones keep home safe)'),
(371112, 1, 3711, 12, 0, 13, 'The Lifeblood Pillar', 'The Lifeblood Pillar, once one of the great crystal pillars of the basin, lies broken. It came down with such force that the earth heaved, and its largest piece, the Sundered Shard, rests where it fell, a cave gaping in its side. Lifeblood elementals drift among the scattered red crystal, and shards of the pillar''s power glitter in the soil. The Scourge walks here now: bonescythe ravagers and monstrous wights stalk the wreckage, and corpses are being dragged toward the Shard.', 'quest 12805 description (the pillar toppled with great force, sending the earth into upheaval; elementals carry its life essence; only four pillars remain); quest 12581 description (the Sundered Shard, the fallen pillar; corpses being dragged there); quest 12579 description (the cave inside the pillar); creature_text 28122 group 4 (Moodle: where are they dragging those bodies?); creature_text 28215 group 9 (Dajik: evil red pillar thing); zone_areas 4295: Lifeblood Elemental x11, Lifeblood Shard x5, Bonescythe Ravager x5, Artruis the Heartless 28659; 4296: Bonescythe Ravager x3, Monstrous Wight 29123, Cultist Corpse 28464'),
(371113, 1, 3711, 13, 0, 13, 'Mosswalker Village', 'Mosswalker Village sits up the ridge northeast of the broken Lifeblood Pillar, the home of the Mosswalker gorlocs and their Great Moss Stone. It is a village of the dead now. Its people lie slaughtered or dying in the moss, blighted corpses and bonescythe ravagers prowl between the huts, and the bodies of the fallen are being dragged away. At Rainspeaker Canopy, Soo-say knew only that the Mosswalkers had stopped coming to the shrine.', 'quest 12578 description (Mosswalker village east, up the ridge, northeast of the broken pillar; not coming to see the shrine); quest 12579 description (Great Moss Stone); quest 12578 reward text (the Mosswalkers were dead; the undead behind it); creature_text 28122 group 4 (where are they dragging those bodies?); zone_areas 4297: Mosswalker Victim 28113 x30, Bonescythe Ravager x13, Blighted Corpse 28641 x7'),
(371114, 1, 3711, 14, 0, 13, 'The Blight Line', 'Beyond the Rainspeaker Rapids, the green of Sholazar ends at the Blight Line. Beyond it lie the Lost Lands, sick and grey, where blighted corpses and bonescythe ravagers roam and the Scourge''s blight spreaders poison the ground, and among them stalks Thalgran Blightbringer. Along the line, the servants of Freya stand against the dead, and at the Rainspeaker Rapids walks the Avatar of Freya herself, a towering guardian who swears to crush every last one of the Scourge''s decrepit bones under her heel.', 'quest 12803 description (the Blight Line between Rainspeaker Rapids and the Lost Lands); npc_text 13303 (Avatar: crush every last one of their decrepit bones under my heel); zone_areas 4283: Bonescythe Ravager x34, Blighted Corpse x32, Blight Spreader 190621, Thalgran Blightbringer 28443, Servant of Freya 28320; 4367: Servant of Freya x12, Bonescythe Ravager x7; 4386: Avatar of Freya 27801, Servant of Freya x31; creature 28443 at 6006,4023 (north of the Avatar)'),
(371115, 1, 3711, 15, 0, 13, 'The Avalanche', 'In the east of the basin the jungle vanishes under a great slide of snow and ice called the Avalanche, and here the Scourge has the run of the land. Snowblind ghouls and frostbitten corpses crowd it in their hundreds, frosthowl screechers circle above, and risen reavers lumber among them. Mighty servants of the Lich King drive the host on: Urgreth of the Thousand Tombs, who swears this land is the Lich King''s now, Bythius the Flesh-Shaper and Hailscorn, with Glonn and Cerberon beside them.', 'zone_areas 4282: Frostbitten Corpse x127, Snowblind Ghoul x119, Frosthowl Screecher x27, Risen Reaver x8, Cerberon 28207, Hailscorn 28208, Glonn 28211, Bythius the Flesh-Shaper 28212, Urgreth of the Thousand Tombs 28103; creature_text 28103 (Urgreth: this land is the Lich King''s now; nothing can stop the Scourge); quest 12546 log text (the Avalanche); warcraft.wiki.gg/wiki/Sholazar_Basin (the Avalanche, the Scourge''s way in after the pillar fell)'),
(371116, 1, 3711, 16, 0, 13, 'The Makers'' Perch and the Waygate', 'Three works of the titans keep their silence at the edges of the basin. The Makers'' Perch stands on the western rim and the Makers'' Overlook high in the eastern mountains, halls of titan stone where stone guardians still stand watch; in the overlook rests a timeworn coffer, locked fast, whose huge stone key one of the guardians carries. At the southern end of the basin stands the third, a titan waygate.', 'quest 12559 description (the Maker''s Perch on the western edge; titans used it to watch over their creations; many stone servants still guard it); quest 12613 description (a second vantage point to the east, high in the mountains); quest 12691 description (stone coffer locked; huge stone key from the Sholazar Guardians; Timeworn Coffer at the Maker''s Overlook); quest 12548 description (the Waygate in the southern end of Sholazar Basin, activated for the first time in seven centuries); zone_areas: Perch Guardian 29013 x5, Sholazar Guardian 28069 x4, Timeworn Coffer 190768 (posarea reads the ground grid, not the halls)'),
(371117, 1, 3711, 17, 0, 13, 'The Stormwright''s Shelf', 'The Stormwright''s Shelf is a broad, flat ledge outside the basin''s lip in the far northwest, above the Makers'' Perch, and few reach it without wings. Storms rule it. Storm revenants and aqueous spirits, the sons of wind and water, roam the rock, giant stormwatchers of metal stand among them, and on the shelf''s western side lies the gorlocs'' Shrine of the Tempest. Low mounds of soaked, fertile earth dot the ground, each holding a strong seed that waits, the gorlocs say, only for the right song.', 'quest 12741 description (large flat area the big-tongues call the Stormwright''s Shelf; only by flying; mighty forces of wind and water; Shrine of the Tempest on its western side); quest 12758 description (giant metal men; outside the basin''s lip, far to the northwest); quest 12737 description (above the Maker''s Perch; small dirt mounds, very fertile, carry a strong seed); zone_areas 4392: Storm Revenant x23, Aqueous Spirit x20, Stormwatcher x3, Perch Guardian x4, Shrine of the Tempest 29079'),
(371120, 2, 3711, 1, 0, 13, 'Avatar of Freya', 'The Avatar of Freya is a towering guardian who walks the Rainspeaker Rapids, where the green of the basin meets the blight. The expedition''s professor speaks of a lifewarden appointed by the titans to look over Sholazar, and she fits the description. The Scourge are a blemish on her pristine lands, and she has sworn by the might of her creators to crush every last one of them. She has no patience for strangers: she knows outlanders are not of this land, and any who will not fight the Lich King''s minions are told to leave before they distract her from her duties.', 'npc_text 13303 (the Scourge a blemish upon these pristine lands; by the might of my creators I will crush every last one); quest 12803 description and reward text (the professor''s lifewarden; you are not of this land, but not with the Scourge); quest 12561 description (if you''re not here to destroy the minions of the Lich King, leave at once; do not distract me from my duties); zone_areas 4386: Avatar of Freya 27801 (one spawn, Rainspeaker Rapids)'),
(371121, 2, 3711, 2, 0, 13, 'High-Shaman Rakjak', 'High-Shaman Rakjak leads the Frenzyheart Tribe from Frenzyheart Hill, and he wants one thing: the land for the Frenzyheart, with the big-tongues gone or dead. He laughs easily, mostly at others, and he is always short of slaves. Outsiders who cross his hunters, such as any stranger who steals a kill from Tracker Gekgek, find themselves sent to him as the tribe''s newest slave and put to work hunting the basin''s apes and wasps beside Frenzyheart hunters who are in no hurry to let them forget it.', 'npc_text 13359 (Frenzyheart will take land for own; big-tongues will leave or we kill them good); quest 12528 description and reward text (Gekgek: you take my kill, now you Frenzyheart slave; Rakjak: good, we running out); quests 12529, 12530, 12533 (hunting hardknuckles and wasps with Goregek and Dajik); quest 12530 reward text (Rakjak squeals loudly and breaks out laughing); creature_text 28214 (Goregek: you always be slave thing to Goregek)'),
(371122, 2, 3711, 3, 0, 13, 'Zepik the Gorloc Hunter', 'Zepik is the best hunter of the Frenzyheart, and his favorite prey is the gorlocs. Apes and wasps bore him; the big-tongues, he says, are not as dumb as the other hunts and give a real fight. He learned to hunt his own way rather than Dajik''s, and not long ago he traveled much of the world on his own; he loves stories of beasts, dragons and gods. Now he sets out on long treks to break the gorloc shrines and frighten their people from the land, and he is glad of a partner who can keep up.', 'quest 12536 description (Zepik is best hunter of the Frenzyheart; long trek to break big-tongue shrine and scare them away); creature_text 28216 groups 0-3 (traveled lot of world on my own not long ago; stories of beasts and dragons and gods; do better my own way than Dajik''s; big-tongues not as dumb as other hunts, give a real fight); quest 12538 description (gorillas and wasps are boring; big-tongues the only thing fun to hunt); quest 12537 completion text (this go much better with partner)'),
(371123, 2, 3711, 4, 0, 13, 'High-Oracle Soo-say', 'High-Oracle Soo-say leads the Oracles from Rainspeaker Canopy, where he keeps the Great Rain Stone and brings it the shinies his people dig up. He is kindly and quick to welcome any stranger who helps his people, though he has a habit of staring at a visitor''s forehead while he talks. His Rainspeakers were in the basin long before the wolvar came, and their home is a sacred place; whatever the puppy-men do, Soo-say will not leave it.', 'npc_text 13361 (the Great Rain Stone; we bring it shinies); quest 12570 reward text (you help us, you welcome then); quest 12574 description (stares at your forehead); quest 12571 description (we were here long before the puppy-men came; very sacred place, we will not leave)'),
(371124, 2, 3711, 5, 0, 13, 'Moodle', 'Moodle is no ordinary Rainspeaker. He has been out in the world and learned the language of outsiders, and he wants it understood at once that he is not as foolish as most Oracles a stranger meets, nor easily duped. Sharp of tongue and weary of running errands for people he has only just met, he has little faith in Soo-say''s forgiving ways: as Moodle sees it, the wolvar will never leave the gorlocs alone, and the only way to stop them is to kill them. There is no peace.', 'quest 12578 completion and reward text (Soo-say far too forgiving; there is no peace; not as foolish as most Oracles; learned your language; not easily duped; knew the Mosswalkers were dead); creature_text 28122 groups 0-3 (digging at the will of someone I just recently met; brain the size of a planet)'),
(371125, 2, 3711, 6, 0, 13, 'Jaloot', 'Jaloot is a Rainspeaker gorloc bursting with energy, who digs faster than anyone, can never have too many shiny crystals, and treasures one favorite crystal above all the rest. Soo-say sends him out with friendly dryskins as a companion, and a cheerful one he is: he chatters about the Great Ones, who he thinks keep the Oracles safe because they know the gorlocs are good and nice, boasts at every fallen foe, and wants nothing more than for his new friends to stay his friends.', 'creature_text 28121 groups 0-3 (shiny crystals; we are fast digger; Great Ones keep home safe because they like Oracles; you''re pretty strong and nice, let''s stay friends; killing spree); quest 12574 description and log text (sending you and Jaloot; Jaloot''s Favorite Crystal); quest 12762 description (Jaloot found a very special crystal in River''s Heart)'),
(371126, 2, 3711, 7, 0, 13, 'Artruis the Heartless', 'Artruis the Heartless, Moodle believes, is the leader of the undead who have poured into Sholazar since the Lifeblood Pillar fell. The trail of corpses his servants drag away points to his lair inside the Sundered Shard, the great fallen piece of the pillar. Moodle wants him found and slain, so that no one is left to drive the dead back upon the gorlocs, but he cannot go himself; whoever goes must find other help.', 'quest 12581 description (find the leader of these undead and kill him; inside the fallen pillar, the Sundered Shard; the corpses being dragged there; Moodle will not be able to accompany you); zone_areas 4295: Artruis the Heartless 28659 (one spawn)'),
(371130, 3, 3711, 1, 0, 13, 'The Stranded Expedition', 'When Archmage Pentarus of Dalaran heard that the legendary Hemet Nesingwary was setting sail for Sholazar Basin, a land said to be a lush paradise in the middle of a frozen continent, he offered to help fund the expedition in return for samples of its exotic plants, reagents and crystals. Then the reports stopped coming. The expedition''s ship had run aground, and its flying machine came through too badly damaged to carry word home. Worse, the Venture Company, digging at the Suntouched Pillar, was harassing Hemet''s scouts and shooting down his supply flights, and Monte Muzzleshot, sent with supplies, ended up hanging by his parachute from a tree in the swamp.', 'quest 12521 description (Pentarus funded Hemet''s expedition; samples of plants, reagents and crystals; lush paradise in a frozen continent; no word; Monte bringing supplies); quest 12521 reward text (cut me down); quest 12489 description and reward text (fool of an archmage; the Venture Company about; Hemet''s welcome); quest 12522 description (the ship ran aground; the flying machine damaged; no means to send reports; Venture Company shot down another flying machine); quest 12524 description (antagonizing our scouts and shooting down supply flights)'),
(371131, 3, 3711, 2, 0, 13, 'The Great Hunt', 'No rough landing will stop Hemet Nesingwary from mastering the largest game Sholazar has to offer, and his companions test every newcomer who wants a place in the hunt. Hemet sends them first against the mighty shardhorn rhinos in the wilds northwest of camp. Buck Cantwell, kept in camp by his injuries, sets them on the dreadsabers, cats that bring down larger game than any he has seen a cat hunt. Debaar, who wants no jokes about the shipwreck, pits them against the mangal crocolisks, wily masters of the ambush. Each of these trials ends, in time, with a single legendary beast.', 'quest 12520 description (no rough landing will stop Hemet; the mighty shardhorn rhino northwest of the camp); quest 12549 description (dreadsabers bring down larger game than I''ve ever seen a cat hunt); quest 12550 description (Buck''s injuries kept him in camp); quest 12551 description (no comments about crashing the ship; the wily mangal crocolisks); quest 12560 description (the crocolisk a master of the ambush)'),
(371132, 3, 3711, 3, 0, 13, 'Frenzyheart and the Oracles', 'The wolvar of the Frenzyheart and the gorlocs of the Oracles are at war over Sholazar, and outsiders are drawn in whether they like it or not. Stealing a kill from the wolvar tracker Gekgek is enough to make a stranger the tribe''s newest slave, sent to Frenzyheart Hill and set to hunting hardknuckle apes and sapphire wasps under hunters like the boastful Goregek and the forgetful Dajik. Hunt well enough and the tribe may come to respect its slave, and the Frenzyheart have no shortage of enemies to hunt.', 'quest 12528 description and reward text (you take my kill; Frenzyheart slave; go to Frenzyheart Hill); quests 12529, 12530, 12533, 12534 (hardknuckles, softknuckles, sapphire wasps); creature_text 28214 (Goregek: Goregek best hunter ever; slave thing); creature_text 28215 (Dajik: we came for something, can''t remember); quest 12531 description (show you better than the other Frenzyheart hunters and Rakjak respect you)'),
(371133, 3, 3711, 4, 0, 13, 'The Lifewarden''s War', 'The forces of undeath have broken into Sholazar, the very cradle of life, and along the Blight Line the Avatar of Freya fights them almost alone. She trusts no outsider. Any stranger who means to stay must first prove they are no minion of the Lich King by destroying the blighted corpses and bonescythe ravagers of the Lost Lands. Even then she is slow to judge, but she allows that there may be something such a stranger can do for her, for the titans'' creations must be defended.', 'quest 12561 description, completion and reward text (the forces of undeath storm the very cradle of life; destroy the minions of the Lich King or leave; the titans'' creations must be defended; perhaps there is something you can do for us); quest 12611 reward text (perhaps I was too quick to judge you); zone_areas 4393: Cultist Infiltrator 28373 x20, Unstable Explosives 190590 x6'),
(371134, 3, 3711, 5, 0, 13, 'The Avatar''s Last Resort', 'As the Scourge gathers for a final push, the Avatar of Freya turns to a last resort, one she will reveal only to an ally whose trust in her is absolute. Its first step is to wake a waygate of the titans. The switches that power it lie in the old vantage points from which the titans watched over their creations, and the first waits inside the Makers'' Perch on the western edge of the basin, where many of their stone servants still stand guard. It is only the first of two.', 'quest 12621 reward text and completion text (the Scourge preparing a final push; last resort; absolute trust); quest 12559 description and reward text (activate the waygate; first switch inside the Maker''s Perch on the western edge; titans used it to watch over their creations; stone servants; one more switch)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(371102, 1, 0, 255, 'With an engine salvaged from a downed flying machine and spare parts carried off from the Venture Company''s dig, Weslex has the Spirit of Gnomeregan flying again. She looks more like a Venture Company shredder now, and he warns riders not to complain about saw blades in their seats, but she carries travelers out of the camp. Her proper restoration will have to wait until the expedition is back in Dalaran.', 'quest 12523 reward text (looking more like a Venture Company shredder; restored when we get back to Dalaran); creature_text 28033 groups 0-3 (saw blades in your seat); npc_text 13042 (Weslex after the repair); spell_area 51116 in 4284 from DONE 12523 (Detect Monte''s Invis (Camp)); creature_template_addon 28037 The Spirit of Gnomeregan, flight master, aura 51114 invisibility type 8'),
(371103, 1, 0, 255, 'When the incense burned by Nozronn''s head, a voice answered. It spoke of the shardhorn patriarch Farunn, who holds himself aloof from his brothers and walks alone north of the Bittertide Falls, needing no defenders. It ended with a warning: once Hemet had claimed his prize, he should leave this land in peace, for he does not belong here. Hemet would have none of it. No dead rhino, he said, tells Hemet Nesingwary where and what he can hunt.', 'creature_text 28256 Voice of Nozronn (Farunn aloof from his brothers; north of the Bittertide Falls; requires no defenders; tell him to leave this land in peace); quest 12544 reward text (no dead rhino tells Hemet Nesingwary where and what he can hunt)'),
(371105, 1, 0, 255, 'Vic has flown over the northeast, and he is not sure what he saw there: to him it looked like a gigantic woman fighting the Scourge. The professor has spoken of a lifewarden appointed by the titans to watch over Sholazar, and Vic suspects this is her. He also knows that if the Scourge crosses from the Lost Lands into the rest of the basin, the expedition is as good as dead.', 'quest 12803 description (not sure what I saw flying to the northeast; gigantic woman; the professor''s lifewarden; if the Scourge cross the border the expedition is as good as dead)'),
(371109, 1, 0, 255, 'To the friends of the Frenzyheart, the hold shows more. Shaman Jakjek stands among the wolvar there in the thick of the battle, and he sees to it that Kartak, for whom the hold is named, never goes hungry. Kartak comes for big-tongue meat, he says, and the Frenzyheart make sure plenty is ready, so that Kartak does not eat them instead.', 'spell_area 52217 (aura 19, see invisibility type 10) in 4287 from DONE 12692; creature_template_addon 28106 Shaman Jakjek aura 52215 (invisibility type 10); his single spawn stands in 4287; npc_text 13364 (Jakjek: Kartak comes for big-tongue meat; Frenzyheart make sure plenty is ready); creature_text 28214 group 5 (Goregek: Frenzyheart feed Kartak big-tongues so Kartak not eat us)'),
(371109, 2, 0, 255, 'Kartak is a great beast, and blood is how the wolvar call it. Oracle blood laid on the altar in the hold brings Kartak to a feast of big-tongues, and if a hunter is worthy, Kartak takes that hunter''s body and lends its rage to the slaughter of the Sparktouched.', 'quest 12703 description (bring Oracle Blood to the altar to call Kartak for a feast of big-tongue; Kartak take your body if you worthy); creature_text 28116 (you feel rage rise within you as your body binds with Kartak); creature_template 28116 Kartak the Abominable (type 1, beast)'),
(371109, 3, 0, 255, 'To the friends of the Oracles, the haven shows more. Lightningcaller Soo-met keeps the Great Lightning Stone here, and though the puppy-men have attacked for days, he says the stone is still safe. Soo-holu has come to help the Sparktouched many times before, and the wolvar, he is sure, do not stand a chance.', 'spell_area 52217 in 4288 from DONE 12695; creature_template_addon 28107 Lightningcaller Soo-met aura 52215 (invisibility type 10); npc_text 13363 (Soo-met: attacking for days; Great Lightning Stone still safe; Soo-holu come to help like many times before)'),
(371109, 4, 0, 255, 'Soo-holu is the protector the Great Ones left at the shrines long ago. It does not know anything is wrong until the shrines are disturbed, so a tainted crystal taken from the wolvar and brought to the Great Lightning Stone calls it to help. Those it trusts, it lets share its body, and through them it turns its power on the Frenzyheart.', 'quest 12705 description (Great Ones left protector long time ago for shrines; it not know something wrong til shrines messed with; bring a bad crystal; Soo-holu take your body); quest 12705 reward text (he more trusting of people he met before); creature_text 28115 (your body binds with that of Soo-holu)'),
(371110, 1, 0, 255, 'Broodmother Slivina is dead. Hemet Nesingwary himself rode against her on the back of a shattertusk mammoth named Stampy, and when it was over he told Dorian the tale: the shaking ride, the fearsome beast, the haze of blood, lead and sweat as her attacks came faster and faster. Dorian, who spent the fight tending the fire and arguing about cogs with Zootfizzle, insists that was epic too, in its own way.', 'creature_text 28451 groups 0-7 (Hemet''s tale; Stampy; blood, lead and sweat); creature_text 28376 group 0 (tending the fire and discussing the drawbacks of cogs); quest 12607 (a shattertusk mammoth to ride into battle with Hemet); quest 12614 reward text'),
(371111, 1, 0, 255, 'The Avatar of Freya tells what the pillars are for. There were five, set around the basin by the titans, who shaped whole forms of life here and let them grow unchecked, and the pillars pour out pure lifeforce. While all five stood, the Scourge could never have broken into the basin. But one of them, the Lifeblood Pillar, has been destroyed.', 'quest 12612 description (titans shaped entire life forms here, fostering their unfettered growth; five crystal pillars emanate pure lifeforce; the Scourge should never have penetrated; one destroyed)'),
(371112, 1, 0, 255, 'No undead could have come near the pillar while it stood, so whoever brought it down was alive. At its foot lay a badly burnt corpse among the remains of powder kegs: one of the Cult of the Damned, the Lich King''s living servants, sent where the dead could not go. The pillar fell to their explosives, and through the breach it left, the Scourge came in.', 'quest 12612 description (no undead could have approached the pillar; look for living intruders) and reward text (burnt corpse, remains of several powder kegs); quest 12608 description (the undead could not enter before the Lifeblood Pillar was brought down; they used their living agents from the Cult of the Damned)'),
(371113, 1, 0, 255, 'Not every Mosswalker was lost. Moodle of the Rainspeakers went through the village with a companion, cutting down the dead and searching the fallen, and some of the gorlocs were still alive. The survivors were sent on to Rainspeaker Canopy. Moodle, who talks down to his people at every turn, admitted he never wants to see any of them die; the Mosswalkers, he said, were good people, and they did not deserve this.', 'quest 12580 description, completion and reward text (rescue victims; some saved, back to Rainspeaker Canopy); creature_text 28122 group 4 (the Mosswalkers were good people; I talk down to them but never want to see any of my people die)'),
(371114, 1, 0, 255, 'Thalgran Blightbringer was the monster most to blame for corrupting the land, the Avatar said, and she sent an ally against him with her ward. It caught his death bolts and turned them back upon him sevenfold until he fell. In these lands, where the power of life rules, she warned, all harm the Lich King''s agents inflict will be returned to them sevenfold.', 'quest 12611 description (Thalgran directly responsible for corrupting the land; Freya''s Ward reflects his deathbolts sevenfold; harm returned sevenfold); quest 12611 reward text'),
(371115, 1, 0, 255, 'Here the Avatar of Freya unleashed the Etymidian. The colossus strode into the Avalanche and tore through the Scourge host, two hundred of its minions and more, and Bythius the Flesh-Shaper, Urgreth of the Thousand Tombs and Hailscorn fell beneath it. The Avatar gave her thanks: life in the basin would go on thriving, while the forces of death raged in the lands around it.', 'quest 12546 description (deploy the Etymidian at the Avalanche; slay 200 Scourge minions, Bythius, Urgreth and Hailscorn); quest 12546 reward text (life will continue to thrive while the forces of death wage in the bordering regions)'),
(371117, 1, 0, 255, 'The Oracles hear an ancient song in the storms of the shelf, the Song of Wind and Water. Played on tempest drums, it calls Haiphoon, the Great Tempest, who devours the sons of typhoon and storm so that the tempest may continue, and the gorlocs believe the Great Tempest looks with favor on those who help him feed.', 'quest 12726 description and reward text (the Stormwright''s Shelf echoes with the Song of Wind and Water; the great tempest devours the sons of typhoons and storms; looks upon us favorably); creature_template 28985 Haiphoon, the Great Tempest'),
(371120, 1, 0, 255, 'Once trust is earned she names herself plainly: the embodiment of a single aspect of Freya, daughter of the titans, left here as the Lifewarden to protect the land against the Scourge. She never imagined the Lich King would send willing living servants to do his work. She could crush them herself, but she cannot leave her post, for she is all that stands between the undead armies and the rest of the basin.', 'quest 12617 description (an embodiment of one aspect of Freya, daughter of the titans; the Lifewarden left to protect this land against the Scourge; all that stands between the undead armies and the basin)'),
(371121, 1, 0, 255, 'A slave who hunts well can win him over. Rakjak laughed long at the tale of the lightning at Mistwhisper Refuge, and he told the slave who had helped call it down that one day, maybe, such a hunter could be an honorary Frenzyheart. Then he gave his most important task: find the injured big-tongue a tracker had spotted by the river and bring it back alive, not to kill it, but to hide it away and poke it until it told him things.', 'quest 12539 reward text (Rakjak like you; maybe one day honorary Frenzyheart); quest 12540 description (capture the injured big-tongue; not bring hunter because they maybe want to kill it; hide it and poke it to make it tell me things)'),
(371122, 1, 0, 255, 'The lich Artruis seized Zepik and used him as a pawn, and only the one who chose to stand with him set him free. Zepik called his rescuer a friend he knew better than any wolvar did, no traitor whatever the others said, and offered to convince the tribe that his rescuer had saved him and beaten the big-tongues. Yet even Zepik, no friend of big-tongues, felt a little bad for the gorloc who died that way: those who fight that well, he said, deserve a fair fight.', 'quest 12582 reward text (I know you weren''t traitor thing; I know you better than all of them; thank you for saving me; I can convince them that you save me and got the big-tongues good; big-tongue dying like that; fair fight); creature_text 28668 (You not catch Zepik sleeping this time)'),
(371123, 1, 0, 255, 'What Soo-say wants is peace. He once sent the Frenzyheart shaman Vekjik an offering and a promise that the Oracles would play nice, and Vekjik answered only with threats. Soo-say was left hurt and puzzled. His people only try to be nice, he says, and the puppy-men only ever answer by being mean; they keep meddling with the great stones, as if they do not know the stones are sacred.', 'quest 12573 description and reward text (peace offering to Shaman Vekjik; tell him we play nice; so mean, we only be nice; they keep messing with great stones, maybe not know they are sacred); npc_text 13137 (Vekjik: go from Frenzyheart land or I call magic stuffs to kill you); creature_text 28315 (Frenzyheart kill you if you come back)'),
(371124, 1, 0, 255, 'Moodle saw what others missed. The undead were never supposed to be able to enter the basin, and he judged that the fall of the Lifeblood Pillar must have let them in; he only wished he had understood sooner how much the pillars and the great stones mattered. Following the corpses the dead were dragging away, he came to suspect that their leader lay inside the Sundered Shard, and sent his companion in after it while he carried the news to Soo-say.', 'quest 12578 reward text (they are not supposed to be able to enter this land; the destruction of the Lifeblood Pillar must have allowed them in); quest 12580 completion text (I wish I had known how key the pillars and the stones were much earlier); quest 12581 description (find the leader inside the Sundered Shard; corpses being dragged there; I''ll bring the news to Soo-say)'),
(371125, 1, 0, 255, 'The lich Artruis took Jaloot captive and used him as a pawn in the Sundered Shard. When the one who chose the Oracles'' side set him free, he was overjoyed. He had seen his friend strike down the puppy-man who had been held there with him, and he was sure it meant that the dryskin was done with the wolvar for good and a friend now of all Oracles.', 'quest 12689 reward text (I knew we friends; good friend for all Oracles; I saw you bonk that puppy-man good; you done with puppy-men; thank you for saving us); creature_text 28667 (now you not catch us with back turned)'),
(371126, 1, 0, 255, 'Artruis, a lich, was waiting. Two brave, ignorant fools, he said, a wolvar and a gorloc who despised each other, had both spoken of their hero, so he had bound them both and shielded himself, offering the hero a chance to choose a side: his spell would hold until the choice was made. He boasted of a hundred years of war and claimed that he could not die, but the shattered crystals of the pillar weakened him, and he fell. Inside his phylactery lay an endless void, and far off, something screaming.', 'creature_text 28659 groups 0-5 (your little friends said you would come; a hundred years of war and suffering; a being that cannot die; the crystals all around weaken me; two brave, ignorant fools despise each other; choose your side quickly to break his spell); quest 12581 completion and reward text (the phylactery; an endless void; screaming in the distance)'),
(371130, 1, 0, 255, 'Debaar would not let the insult stand: Hemet''s expedition came to hunt, and hunt it would. The company''s workers at Swindlegrin''s Dig were cut down, and Foreman Swindlegrin and his ogre bodyguard Meatpie with them. Debaar was relieved to be rid of the trouble, though it was not a fight she would have joined herself. A game hunter, she says, cannot in good conscience lift her weapon against another person.', 'quest 12524 description (we can''t allow this insult to stand; Hemet''s expedition came to hunt, and hunt it shall); quest 12525 description and reward text (Swindlegrin and Meatpie; the Venture Company will trouble us no more; a game hunter cannot lift her weapon against another person)'),
(371130, 2, 0, 255, 'One of the expedition was still missing. Engineer Helice had gone to the Suntouched Pillar to explore its crystals and take samples, and the goblins had overpowered her and kept her at the dig. Freed at last, she fought her way out, blowing up the company''s own cartloads of explosives as she went, and made it back to camp, where everyone had begun to worry when she did not return.', 'quest 12688 description and reward text (came to explore the crystals and take samples; overpowered; we started to get worried when she didn''t return); creature_text 28787 (another cartload of explosives; tell Hemet to expect me)'),
(371131, 1, 0, 255, 'The rhino patriarch Farunn, found with the help of a gorloc oracle and the bones of a dead rhino, fell near the shore of Bittertide Lake, and Hemet, turning its horn in his hands, called it an astounding trophy. Then his eyes turned north. There were rumors, he said, of even bigger, more ferocious game in the northern reaches of the basin.', 'quest 12556 description and reward text (Farunn on the northeast shore of Bittertide Lake; an astounding trophy; even bigger game in the northern reaches)'),
(371131, 2, 0, 255, 'Buck had heard the natives tell of a great dreadsaber they call Shango, but his injuries kept him from looking for proof. Tracks found on the southern shore of Bittertide Lake proved the tale, and Shango was stalked to the falls that feed the lake and slain there. His pelt, Buck declared, was exquisite, and the pursuit flawless: the work of a true huntsman.', 'quest 12550 description (natives tell stories of Shango; injuries kept me in camp; tracks on the southern shore of Bittertide Lake); quest 12558 description and reward text (western shore near the falls; exquisite pelt; a true huntsman)'),
(371131, 3, 0, 255, 'Debaar''s plan for the crocolisk they call Bushwhacker was to beat the ambusher at his own game, hiding a hunter on the western beach of River''s Heart under a disguise of sandfern. The disguise did not fool him. The kill happened all the same, and Debaar, a little put out, had to admit that the jaw was truly a monster''s and that Hemet would be proud.', 'quests 12560 and 12569 descriptions (camouflage of sandfern; western beach of River''s Heart); quest 12569 reward text (the failure of the disguise; you did manage to get the kill; this crocolisk was truly a monster)'),
(371132, 1, 0, 255, 'Rakjak sent his best slave with Zepik on a long trek to Mistwhisper Refuge. Zepik knew the gorlocs fed their rain shrines with crystals and that the wrong ones drove the clouds mad, so the two smashed blue crystals before the Great Mist Stone. Lightning struck an oracle down, Zepik cackled with glee, and the hunters killed Mistwhispers until it was time to walk home. Back on the hill, Rakjak laughed too.', 'quest 12536 description (long trek to break big-tongue shrine); quest 12537 description and reward text (crystals power the rain shrines; the wrong crystals make the clouds go crazy; lightning smash that oracle guy); quest 12538 description (kill lots of mist big-tongues); quest 12539 description and reward text (walk home; blown up by lightning; Rakjak breaks out laughing)'),
(371132, 2, 0, 255, 'Rakjak wanted a wounded gorloc brought in alive, to hide and question. But the injured Rainspeaker, terrified and grateful to be spared, asked its captor to come home with it instead, since the puppy-men were kind of mean anyway. At Rainspeaker Canopy the Oracles eyed the stranger who stank of puppy-men, then welcomed the one who had helped them.', 'quest 12540 description and reward text (capture the injured big-tongue; no kill me please); quest 12570 description, completion and reward text (you save me; come with us; puppy-men kind of mean anyway; you stink of puppy-men; you welcome then); npc_text 13137 (Vekjik: disgusting big-tongue friend)'),
(371132, 3, 0, 255, 'The smashed crystals had brought rain and lightning down on the Mistwhispers, and in the confusion the wolvar warlord Tartek stole the treasure they had found in the sea-lake for their Great Mist Stone. Mistcaller Soo-gan, who thought the newcomer''s face somehow familiar, trusted Soo-say''s word and asked for help. Tartek was slain, the treasure taken back, and the spearbearers at the wolvar camp to the north cut down. The Mistcaller was sure the puppy-men would leave them alone now.', 'quest 12574 reward text (we think we seen you before; Soo-say said you good); quest 12575 description (puppy-men smashed blue crystals at the Great Mist Stone; Tartek stole the treasure found in the sea-lake; the camp to the north); quest 12576 description (make puppy-men stop and not come back); quest 12577 description (Mistwhisper safe, treasure safe, puppy-men sure to leave us alone); creature_text 28105 (Warlord Tartek)'),
(371133, 1, 0, 255, 'The trail of the pillar''s destroyer changed everything. The Avatar had been searching for the wrong enemy all along, for she had never imagined that the living would willingly serve the Lich King. Learning that the Cult of the Damned was at work in her lands, she wasted no time: the cultists, she declared, would be uprooted from Sholazar.', 'quest 12608 reward text (the living willingly serve the Lich King? all this time I''ve been searching for the wrong enemy; uproot these cultists from these lands)'),
(371133, 2, 0, 255, 'The cultists had made their camp at the Death''s Hand Encampment, with explosives they meant to turn on the land, and they were cut down there. It came too late. Even as the camp fell, the Avatar sensed more of them at the Glimmering Pillar, making ready to bring it down as they had the Lifeblood, and she gave her ally a horn to blow atop the pillar and channel her power through its crystal.', 'quests 12617 and 12660 descriptions and reward text (Death''s Hand Encampment; cultist infiltrators; unstable explosives; dealt with, but it might have been too late); quest 12620 description (cultists at the Glimmering Pillar preparing to destroy it; blow this horn atop the pillar to channel my power through the crystal)'),
(371133, 3, 0, 255, 'The Avatar''s power broke the cultists at the Glimmering Pillar, and she owned that a mere mortal had proved a worthier ally than she expected. It was not enough. The Scourge showed no sign of stopping and was gathering for a final push, and the Avatar spoke of a last resort, one she would reveal only to someone whose trust was absolute, and from which there would be no turning back.', 'quest 12620 reward text (impressive; I wasn''t expecting a mere mortal to prove as worthy an ally; our efforts have not been sufficient; the Scourge shows no signs of stopping); quest 12621 description, completion and reward text (a last resort; absolute trust; the Scourge preparing for a final push; no turning back)'),
(371134, 1, 0, 255, 'The second switch lay in the Makers'' Overlook, high in the eastern mountains. With both thrown, the waygate at the southern end of the basin woke for the first time in seven centuries. Through it, the Avatar said, lay the basin''s final hope, the weapon called the Etymidian, and with it she meant to put an end to those who would bring the taint of undeath to her pristine land.', 'quest 12613 description and reward text (a second vantage point to the east, high in the mountains; the waygate is active); quest 12548 description and log text (the Waygate in the southern end of Sholazar Basin, activated for the first time in seven centuries; where our final hope lies; unleash the Etymidian)'),
(371134, 2, 0, 255, 'Beyond the gate, in a distant land, stood a colossus of stone. The engravings carved upon it left no doubt that this was the weapon the Avatar had spoken of. This was the Etymidian.', 'quest 12548 reward text (as you read the engravings on this stone colossus, you realize this is the weapon Freya spoke of)'),
(371134, 3, 0, 255, 'Once awake, the Etymidian sensed the essence of Sholazar fraying under the blight of undeath. Only Freya''s power could grant it passage into her lands, so it bound its being into a rune, to be carried back through the waygate to the Avatar. When the rune reached her hands, she spoke a promise: woe to all who serve the Lich King and threaten the titans'' creations, for the Etymidian is here.', 'quest 12797 description and reward text (I can sense the essence of Sholazar Basin begin to fray; I''ve bound my being into the rune; only her power can grant me passage; the Etymidian is here)');
